package com.adib.maintenance;
import android.content.*;import android.graphics.*;import android.graphics.drawable.*;import android.view.*;import android.widget.*;import org.json.*;import java.util.*;
final class CompactDesign {
 static int dp(Context c,float n){return Math.round(n*c.getResources().getDisplayMetrics().density);}
 static Drawable icon(Context c,String kind,int color){return new Glyph(c,kind,color);}
 static final class Glyph extends Drawable {final Paint p=new Paint(3);final String kind;final int size;Glyph(Context c,String k,int color){kind=k;size=dp(c,22);p.setColor(color);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(1.6f);p.setStrokeCap(Paint.Cap.ROUND);p.setStrokeJoin(Paint.Join.ROUND);}public void draw(Canvas c){Rect b=getBounds();int save=c.save();c.translate(b.left,b.top);c.scale(b.width()/24f,b.height()/24f);Path q=new Path();switch(kind){case "menu":for(int y:new int[]{6,12,18})c.drawLine(4,y,20,y,p);break;case "search":c.drawCircle(10,10,7,p);c.drawLine(15,15,21,21,p);break;case "chat":c.drawRoundRect(3,4,21,18,3,3,p);q.moveTo(8,18);q.lineTo(5,22);q.lineTo(5,18);c.drawPath(q,p);c.drawLine(7,9,17,9,p);c.drawLine(7,13,14,13,p);break;case "tasks":q.moveTo(5,12);q.lineTo(10,17);q.lineTo(20,6);c.drawPath(q,p);break;case "matrix":for(int x:new int[]{3,14})for(int y:new int[]{3,14})c.drawRect(x,y,x+7,y+7,p);break;case "timer":c.drawCircle(12,12,9,p);c.drawLine(12,7,12,12,p);c.drawLine(12,12,16,15,p);break;case "calendar":c.drawRoundRect(4,5,20,21,1,1,p);c.drawLine(4,10,20,10,p);c.drawLine(8,3,8,7,p);c.drawLine(16,3,16,7,p);break;case "equipment":q.moveTo(12,3);q.lineTo(21,8);q.lineTo(21,18);q.lineTo(12,23);q.lineTo(3,18);q.lineTo(3,8);q.close();c.drawPath(q,p);c.drawLine(3,8,12,13,p);c.drawLine(12,13,21,8,p);c.drawLine(12,13,12,23,p);break;default:for(int y:new int[]{5,12,19})c.drawCircle(12,y,.6f,p);}c.restoreToCount(save);}public int getIntrinsicWidth(){return size;}public int getIntrinsicHeight(){return size;}public void setAlpha(int a){p.setAlpha(a);}public void setColorFilter(ColorFilter f){p.setColorFilter(f);}public int getOpacity(){return PixelFormat.TRANSLUCENT;}}
 static void workers(LinearLayout parent,JSONObject task,boolean dark){JSONArray names=task.optJSONArray("tapsirildi");if(names==null||names.length()==0)names=task.optJSONArray("assignees");if(names==null||names.length()==0)return;TextView t=new TextView(parent.getContext());t.setText(android.text.TextUtils.join(" · ",jsonStrings(names)));t.setTextSize(11);t.setTextColor(dark?0xffd1d9b1:0xff667447);t.setPadding(dp(parent.getContext(),9),dp(parent.getContext(),4),dp(parent.getContext(),9),dp(parent.getContext(),4));t.setBackground(HybridUi.rounded(dark?0xff3c483a:0xfff3f6c9,dp(parent.getContext(),12),0,0));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-2,-2);lp.topMargin=dp(parent.getContext(),6);parent.addView(t,lp);}
 static List<String> jsonStrings(JSONArray a){List<String> n=new ArrayList<>();for(int i=0;i<a.length();i++){Object v=a.opt(i);String s=v instanceof JSONObject?((JSONObject)v).optString("name"):String.valueOf(v);if(!s.isEmpty()&&!s.equals("null"))n.add(s);}return n;}
 static String group(JSONObject t){if(t.optBoolean("completed")||t.optString("status").equals("Done"))return "Tamamlanmış";String d=t.optString("date");if(d.isEmpty())return "Tarixsiz";String today=WorkTimerClient.at(WorkTimerClient.anchor>0?WorkTimerClient.now():System.currentTimeMillis()).substring(0,10);String day=d.length()>=10?d.substring(0,10):d;return day.compareTo(today)<0?"Gecikmiş":day.equals(today)?"Bu gün":"Növbəti";}
 static final class Groups {final LinearLayout host;final boolean dark;final LinkedHashMap<String,LinearLayout> boxes=new LinkedHashMap<>();final Map<String,TextView> labels=new HashMap<>();final Map<String,Integer> counts=new HashMap<>();Groups(LinearLayout h,boolean d){host=h;dark=d;}void add(JSONObject task,View row,boolean grouped){if(!grouped){host.addView(row);return;}String key=group(task);LinearLayout box=boxes.get(key);if(box==null){box=new LinearLayout(host.getContext());box.setOrientation(1);box.setPadding(dp(host.getContext(),14),dp(host.getContext(),10),dp(host.getContext(),14),dp(host.getContext(),5));box.setBackground(HybridUi.rounded(HybridUi.surface(dark),dp(host.getContext(),18),0,0));TextView title=new TextView(host.getContext());title.setTextSize(13);title.setTypeface(null,Typeface.BOLD);title.setTextColor(HybridUi.muted(dark));title.setPadding(0,dp(host.getContext(),4),0,dp(host.getContext(),8));box.addView(title);labels.put(key,title);boxes.put(key,box);}int count=counts.containsKey(key)?counts.get(key)+1:1;counts.put(key,count);labels.get(key).setText(key+"  ·  "+count);row.setBackgroundColor(Color.TRANSPARENT);box.addView(row);}void finish(){for(String key:new String[]{"Bu gün","Gecikmiş","Növbəti","Tarixsiz","Tamamlanmış"}){LinearLayout box=boxes.get(key);if(box==null)continue;LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=dp(host.getContext(),12);host.addView(box,lp);}}}
}
